class Solution {
    fun totalFruit(fruits:IntArray):Int{
        val frequency=mutableMapOf<Int,Int>();
        var left=0;
        var answer=0;
        for(right in fruits.indices){
            frequency[fruits[right]]=(frequency[fruits[right]]?:0)+1;
            while(frequency.size>2){
                val value=fruits[left++];
                val count=frequency[value]!!-1;
                if(count==0)frequency.remove(value)else frequency[value]=count
            };
            answer=maxOf(answer,right-left+1)
        };
        return answer
    }
}

code.cpp:
class Solution {
    public: int totalFruit(vector<int>& fruits){
        unordered_map<int,int> frequency;
        int left=0,answer=0;
        for(int right=0;right<(int)fruits.size();++right){
            ++frequency[fruits[right]];
            while(frequency.size()>2){
                int value=fruits[left++];
                if(--frequency[value]==0)frequency.erase(value);
            }
            answer=max(answer,right-left+1);
        }
        return answer;
    }
};
